LABELS=dict(NAMES,corrected_fixed='Referanse: korrigert historikk',operational_fixed='Referanse: dagens operative modell',weather_actual='Vær: faktisk kampvær',weather_noise_1='Vær: syntetisk feilnivå 1',weather_noise_2='Vær: syntetisk feilnivå 2')
def read(p):return json.loads(p.read_text())
def main():
    assert read(P/'outcome_source_verification.json')['passed']
