    scores=pd.read_csv(P/'scores.csv');wide=scores.pivot(index='arm',columns='season',values='net');wide['mean']=wide[EVAL].mean(axis=1,skipna=False);gates={v['arm']:v for v in verified['utility_gates']};winners=[a for a in ARMS if gates[a]['passed']];best=wide.loc[ARMS].sort_values('mean',ascending=False).index[0]
