            pred=pd.read_csv(P/'trajectories'/f'{season}_{arm}.csv.gz');q=base.merge(pred[KEY+[f'xp_{j}' for j in range(8)]],on=KEY,validate='one_to_one')
            for h in [1,3,8]:
                z=q[q.teacher_eligible&(q['round']+h-1<=38)&q[[f'y_{j}' for j in range(h)]].notna().all(axis=1)];k=(season,h);signature=sha_keys(z)
                if k in keys:assert keys[k]==signature
