    statuspath=R/'overview/COMMON_COMPARISON_STATUS.json';status=read(statuspath);status.update(status='completed_verified_forecasts_and_season_attempts',manager_simulations_run=True,manager_full_seasons=full,manager_attempted_seasons=46,manager_technical_stops=stops,manager_decisions_verified=decisions,manager_result=str((P/'result.json').relative_to(R)),overview_sha256=sha(overview),utility_gate_winners=winners);statuspath.write_text(json.dumps(status,ensure_ascii=False,indent=2)+'\n')
