def fmt(value,digits=0,sign=False):
    return '—' if pd.isna(value) else format(value,('+' if sign else '')+'.'+str(digits)+'f')
def sha_keys(d):
    import hashlib
    return hashlib.sha256(d[KEY].sort_values(KEY).to_csv(index=False).encode()).hexdigest()
if __name__=='__main__':main()
